#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

if (( BASH_VERSINFO[0] < 3 )); then echo "This wizard needs bash 3.2 or newer; this is bash $BASH_VERSION." >&2; exit 1; fi

case "$(uname -s)" in
  Darwin) MODE=mac ;;
  Linux)
    if command -v wslpath >/dev/null 2>&1; then MODE=wsl
    else echo "On Linux this wizard runs only inside WSL (it needs wslpath to hand files to Windows Chrome). Run it on a Mac or in WSL." >&2; exit 1; fi ;;
  *) echo "Unsupported system $(uname -s): this wizard runs on macOS or in WSL." >&2; exit 1 ;;
esac

if [[ "$MODE" == mac ]]; then
  CHROME_NAME="Mac Chrome"
  DEVTOOLS_KEYS="Cmd+Option+J"
  MACHINE_LABEL="macOS Chrome, backend on the same Mac"
else
  CHROME_NAME="Windows Chrome"
  DEVTOOLS_KEYS="Ctrl+Shift+J"
  MACHINE_LABEL="Windows Chrome, backend in WSL"
fi

cd "$(dirname "$0")/../.."

TOTAL_STAGES=9

PROBE_DIR="data/probe"
EXPORT_DIR="$PROBE_DIR/export"
BACKEND_LOG="$PROBE_DIR/backend.log"
BACKEND_URL="http://127.0.0.1:4317"
BACKEND_PID=""
BACKEND_SETSID=false
OBS_JSON=""
GRAB_SNIPPET="(() => { const q = document.querySelector('video').getVideoPlaybackQuality(); return q.droppedVideoFrames + ' ' + q.totalVideoFrames; })()"

command -v bun >/dev/null 2>&1 || { echo "bun is not on PATH." >&2; exit 1; }
command -v curl >/dev/null 2>&1 || { echo "curl is not on PATH." >&2; exit 1; }

# Stops only the pid this wizard started, and its process group only when setsid made it a group leader. SIGTERM lets the backend close its database.
stop_backend() {
  [[ -n "$BACKEND_PID" ]] || return 0
  if kill -0 "$BACKEND_PID" 2>/dev/null; then
    if [[ "$BACKEND_SETSID" == true ]]; then
      kill -TERM -- "-$BACKEND_PID" 2>/dev/null || kill -TERM "$BACKEND_PID" 2>/dev/null || true
    else
      kill -TERM "$BACKEND_PID" 2>/dev/null || true
    fi
    for _ in $(seq 1 50); do kill -0 "$BACKEND_PID" 2>/dev/null || break; sleep 0.1; done
    if kill -0 "$BACKEND_PID" 2>/dev/null; then
      if [[ "$BACKEND_SETSID" == true ]]; then kill -KILL -- "-$BACKEND_PID" 2>/dev/null || true; else kill -KILL "$BACKEND_PID" 2>/dev/null || true; fi
    fi
  fi
  BACKEND_PID=""
}
trap stop_backend EXIT

# yesno "question" sets YN to true or false (the library's confirm returns nonzero on no, which set -e would turn into an exit).
yesno() { if confirm "$1"; then YN=true; else YN=false; fi; }

# observe "question" records a yes/no answer as an unscored observation. Questions must not contain double quotes.
observe() {
  yesno "$1"
  OBS_JSON+="${OBS_JSON:+,}{\"question\":\"$1\",\"answer\":$YN}"
}

# ask_pair VAR "prompt" reads "<dropped> <total>" (two non-negative integers) into VAR.
ask_pair() {
  local var="$1" prompt="$2"
  while true; do
    ask "$var" "$prompt"
    [[ "${!var}" =~ ^[0-9]+[[:space:]]+[0-9]+$ ]] && break
    warn "Expected two whole numbers separated by a space, like: 3 7200"
  done
}

open_file() {
  if [[ "$MODE" == mac ]]; then
    printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$1"
    open "$1" >/dev/null 2>&1 || warn "open failed; open this file yourself: $1"
    return 0
  fi
  local win; win="$(wslpath -w "$1")"
  if command -v explorer.exe >/dev/null 2>&1; then
    printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$win"
    explorer.exe "$win" >/dev/null 2>&1 || true
  else
    warn "explorer.exe not found; open this file yourself: $win"
  fi
}

# max_control_seq prints the highest seq of any control fact stored so far (0 if none), so a stop from an earlier run is not mistaken for this one.
max_control_seq() {
  DB="$PROBE_DIR/afterclass.sqlite" bun -e '
    import { Database } from "bun:sqlite";
    try {
      const db = new Database(process.env.DB, { readonly: true });
      console.log(db.query("SELECT COALESCE(MAX(seq), 0) AS m FROM capture_facts WHERE kind = ?").get("control").m);
    } catch { console.log(0); }
  ' 2>/dev/null || echo 0
}

# stop_after SEQ prints yes when a stop control fact newer than SEQ is stored, else no.
stop_after() {
  DB="$PROBE_DIR/afterclass.sqlite" AFTER="$1" bun -e '
    import { Database } from "bun:sqlite";
    try {
      const db = new Database(process.env.DB, { readonly: true });
      const row = db.query("SELECT 1 AS x FROM capture_facts WHERE kind = ? AND seq > ? AND json_extract(body_json, ?) = ? LIMIT 1").get("control", Number(process.env.AFTER), "$.action", "stop");
      console.log(row ? "yes" : "no");
    } catch { console.log("no"); }
  ' 2>/dev/null || echo no
}

# samples_tsv KIND prints "index, video id, whole seconds, text" rows; a missing video id or text is "-".
samples_tsv() {
  SAMPLES="$EXPORT_DIR/samples.json" KIND="$1" bun -e '
    const s = JSON.parse(await Bun.file(process.env.SAMPLES).text());
    const clean = (t) => String(t).replace(/\s+/g, " ");
    const row = (x, at, text) => [x.index, x.videoId || "-", Math.floor(at), text || "-"].join("\t");
    const range = (x) => "[" + x.start + ", " + x.end + ")";
    const k = process.env.KIND;
    if (k === "captions") for (const c of s.captions.samples) console.log(row(c, c.mediaS, clean(c.text)));
    else if (k === "frames") for (const f of s.frames.samples) console.log(row(f, f.mediaS, ""));
    else if (k === "ad-frames") for (const f of s.adCandidates.frames) console.log(row(f, f.mediaS, ""));
    else if (k === "ad-passages") for (const p of s.adCandidates.passages) console.log(row(p, p.start, range(p) + " " + clean(p.text)));
    else if (k === "ad-spans") for (const p of s.adCandidates.spans) console.log(row(p, p.start, range(p)));
  '
}

banner "After Class: capture probe (experiment 1)"

# ── Stage 1 ───────────────────────────────────────────────────────────────
stage "Build the extension"
say "This run is free: the backend runs in replay mode, so no Jev call and no Claude call is made."
if [[ ! -d node_modules ]]; then
  say "node_modules is missing, so installing the pinned dependencies."
  bun install --frozen-lockfile
fi
if [[ "$MODE" == mac ]]; then
  BUN_VERSION="$(bun --version 2>/dev/null || true)"
  [[ "$BUN_VERSION" == "1.4.3" ]] || warn "bun is ${BUN_VERSION:-of unknown version}, but this repo pins 1.4.3. Continuing; results on another Bun version are not what was tested."
  bun run build:ext
  EXT_SHOW="$PWD/dist/extension"
else
  WIN_PROFILE="$( (cd /mnt/c 2>/dev/null && cmd.exe /c 'echo %USERPROFILE%' 2>/dev/null | tr -d '\r') || true )"
  EXT_PARENT=""
  if [[ -n "$WIN_PROFILE" ]] && EXT_PARENT="$(wslpath -u "$WIN_PROFILE" 2>/dev/null)" && [[ -d "$EXT_PARENT" ]]; then
    note "Windows profile folder: $WIN_PROFILE"
  else
    warn "Could not read your Windows profile folder."
    while true; do
      ask WIN_PROFILE "Windows folder to hold the extension (like C:\\Users\\you):"
      EXT_PARENT="$(wslpath -u "$WIN_PROFILE" 2>/dev/null || true)"
      [[ -n "$EXT_PARENT" && -d "$EXT_PARENT" ]] && break
      warn "That folder does not exist from WSL."
    done
  fi
  EXT_DIR="$EXT_PARENT/afterclass-extension"
  EXT_SHOW="$(wslpath -w "$EXT_DIR")"
  say "Chrome does not load extensions from \\\\wsl\$ paths, so the build is copied to a Windows folder."
  AFTERCLASS_EXT_OUT="$EXT_DIR" bun run build:ext
fi
printf '\n'
say "Folder to pick in Chrome:"
printf '  %s%s%s\n' "$BOLD" "$EXT_SHOW" "$RESET"

# ── Stage 2 ───────────────────────────────────────────────────────────────
stage "Load the extension in Chrome"
step "In $CHROME_NAME, open chrome://extensions (type it in the address bar)."
step "Turn on Developer mode (top right)."
step "Click Load unpacked and choose: $EXT_SHOW"
note "If you rebuilt into the same folder, click the reload arrow on the After Class card instead."
step "Copy the 32-letter ID shown on the After Class card. It is public."
while true; do
  ask AFTERCLASS_EXTENSION_ID "Extension ID:"
  [[ "$AFTERCLASS_EXTENSION_ID" =~ ^[a-p]{32}$ ]] && break
  warn "An extension ID is exactly 32 letters, each from a to p."
done
write_env AFTERCLASS_EXTENSION_ID "$AFTERCLASS_EXTENSION_ID"

# ── Stage 3 ───────────────────────────────────────────────────────────────
stage "Start the backend (capture-only)"
if curl -fsS --max-time 2 "$BACKEND_URL/health" >/dev/null 2>&1; then
  warn "Something already answers on $BACKEND_URL. Stop that backend first, then re-run this wizard."
  exit 1
fi
mkdir -p "$PROBE_DIR"
: > "$BACKEND_LOG"
say "Starting: AFTERCLASS_MODE=replay AFTERCLASS_DATA=$PROBE_DIR bun run src/backend/main.ts"
# bun runs main.ts directly (not through the dev script) so $! is the backend's own pid.
BACKEND_CMD=(bun run src/backend/main.ts)
if command -v setsid >/dev/null 2>&1; then BACKEND_SETSID=true; BACKEND_CMD=(setsid "${BACKEND_CMD[@]}"); fi
# The log is redacted so the pairing token never lands in a file this wizard wrote; the wizard shows it on screen only.
AFTERCLASS_MODE=replay AFTERCLASS_DATA="$PROBE_DIR" AFTERCLASS_EXTENSION_ID="$AFTERCLASS_EXTENSION_ID" \
  "${BACKEND_CMD[@]}" > >(awk '{ if ($0 ~ /^pairing token: /) print "pairing token: [hidden in this log; shown by the wizard]"; else print; fflush() }' > "$BACKEND_LOG") 2>&1 &
BACKEND_PID=$!
note "backend pid $BACKEND_PID (the wizard stops this pid and nothing else when it exits)"
for _ in $(seq 1 240); do
  grep -q '^pairing token:' "$BACKEND_LOG" 2>/dev/null && break
  if ! kill -0 "$BACKEND_PID" 2>/dev/null; then
    warn "The backend exited. Its log:"
    cat "$BACKEND_LOG"
    exit 1
  fi
  sleep 0.5
done
grep -q '^pairing token:' "$BACKEND_LOG" || { warn "No pairing token line after 2 minutes. Log:"; cat "$BACKEND_LOG"; exit 1; }
if ! grep -q '^mode: replay' "$BACKEND_LOG"; then
  warn "The backend did not report replay mode, so this would not be a free run. Stopping."
  exit 1
fi
PAIRING_TOKEN="$(cat "$HOME/.config/afterclass/pairing-token" 2>/dev/null || true)"
[[ -n "$PAIRING_TOKEN" ]] || { warn "Could not read $HOME/.config/afterclass/pairing-token."; exit 1; }
say "Backend is up in replay mode. Pairing token (shown here only, stored nowhere by this wizard):"
printf '  %s%s%s\n' "$BOLD" "$PAIRING_TOKEN" "$RESET"
if [[ "$MODE" == mac ]]; then
  curl -fsS --max-time 3 "$BACKEND_URL/health" >/dev/null || { warn "The backend did not answer $BACKEND_URL/health. Its log:"; cat "$BACKEND_LOG"; exit 1; }
  say "$BACKEND_URL/health answered from this Mac."
  say "Now check that Mac Chrome shows it too."
  open_url "$BACKEND_URL/health"
  yesno "Did Mac Chrome show a response (not a connection error)?"
  if [[ "$YN" != true ]]; then
    warn "Mac Chrome could not show the backend's health page, and I have not diagnosed why."
    note "Stop here and tell Claude exactly what Chrome shows; do not continue with a broken link."
    exit 1
  fi
else
  curl -fsS --max-time 3 "$BACKEND_URL/health" >/dev/null && say "WSL reaches its own backend: $BACKEND_URL/health answered."
  say "Now check that Windows Chrome reaches it too."
  open_url "$BACKEND_URL/health"
  yesno "Did Windows Chrome show a response (not a connection error)?"
  if [[ "$YN" != true ]]; then
    warn "Windows Chrome could not reach the backend, and I have not diagnosed why."
    note "What to look at: WSL2 forwards localhost to Windows by default (the localhostForwarding setting in .wslconfig, documented default true)."
    note "A firewall prompt or rule on Windows, or a networking mode other than the default, can also change this."
    note "Stop here and tell Claude exactly what Chrome shows; do not continue with a broken link."
    exit 1
  fi
fi

# ── Stage 4 ───────────────────────────────────────────────────────────────
stage "Pair the extension with the backend"
step "In Chrome open chrome://extensions, find After Class, click Details, then Extension options."
step "Paste the pairing token shown in stage 3 into the Pairing token box."
step "Click Save and test."
say "Expected message: Connected to the backend."
yesno "Does the page say exactly: Connected to the backend."
if [[ "$YN" != true ]]; then
  warn "Not paired. Fix this before capturing: check the Extension ID (stage 2) and the token."
  exit 1
fi

# ── Stage 5 ───────────────────────────────────────────────────────────────
stage "Performance baseline: capture OFF"
say "Approved acceptance lectures:"
note "  Chalkboard: MIT 18.06 Lecture 1, The geometry of linear equations (find it on MIT OpenCourseWare's YouTube channel)."
note "  Diagrams:   Georgia Tech, Lamport's clocks lesson: https://www.youtube.com/watch?v=QgWz_s7uugE"
note "Use the chalkboard one if you can: bar 3 is about board text."
while true; do
  ask LECTURE_URL "Lecture URL (https://www.youtube.com/watch?v=...):"
  [[ "$LECTURE_URL" =~ ^https://(www\.)?youtube\.com/watch\?v=[A-Za-z0-9_-]{11}([&#].*)?$ ]] && break
  warn "That does not look like a youtube.com/watch URL."
done
write_env LECTURE_URL "$LECTURE_URL"
say "Capture stays OFF for this step: do not click Start capture."
open_url "$LECTURE_URL"
note "It opens in your default browser. If that is not Chrome, paste the URL into Chrome."
step "Use a fresh page load of the video (the counters start at zero when the page loads)."
step "If an ad plays first, skip it or reload the page: ad frames would count in the numbers."
step "Play the first 2 minutes without pausing or seeking."
step "At 2:00, press $DEVTOOLS_KEYS to open the Console, and run this (type 'allow pasting' first if Chrome asks):"
printf '    %s%s%s\n' "$BOLD" "$GRAB_SNIPPET" "$RESET"
ask_pair OFF_NUMBERS "Paste the two numbers it printed (dropped total):"
read -r OFF_DROPPED OFF_TOTAL <<< "$OFF_NUMBERS"

# ── Stage 6 ───────────────────────────────────────────────────────────────
stage "Capture ON, then a longer watch"
CONTROL_SEQ_AT_START="$(max_control_seq)"
step "Load the same URL again, fresh (reload the tab)."
step "Click the After Class toolbar icon (puzzle piece menu if hidden), then Start capture. The headline should read Capturing."
step "Play the same first 2 minutes without pausing or seeking."
step "At 2:00 run the same snippet in the Console:"
printf '    %s%s%s\n' "$BOLD" "$GRAB_SNIPPET" "$RESET"
ask_pair ON_NUMBERS "Paste the two numbers it printed (dropped total):"
read -r ON_DROPPED ON_TOTAL <<< "$ON_NUMBERS"
printf '\n'
say "Keep watching with capture on for at least 10 more minutes. During that time do each of these:"
step "Pause the video, wait a few seconds, resume."
step "Seek back about 30 seconds and rewatch that part."
step "Change the speed to 1.5x for a while, then back to 1x."
step "Let an ad play if YouTube serves one."
warn "An ad cannot be forced. If none appears, the ad bar is reported NOT MEASURED, not passed."
pause "When you have watched 10+ more minutes and done the steps above, press Enter."
printf '\n'
say "Now three observations. They are recorded as your answers and are not scored against any bar."
observe "Does the popup show the video title and a caption status such as Captions found?"
say "Next one was flagged earlier as never checked in real Chrome. In the popup, click Review now."
note "This run is capture-only, so the review may say it is not ready. Answer yes if a tab opens on the review app."
observe "Did Review now open a tab on the review app at 127.0.0.1:4317 that shows this capture?"
observe "Did an ad play during the capture?"

# ── Stage 7 ───────────────────────────────────────────────────────────────
stage "Stop the capture and the backend"
step "In the popup click Stop. The headline should change to Stopped."
pause "Press Enter once the popup says Stopped."
say "Waiting for the backend to store the stop."
STOPPED=false
while [[ "$STOPPED" != true ]]; do
  for _ in $(seq 1 30); do
    if [[ "$(stop_after "$CONTROL_SEQ_AT_START")" == "yes" ]]; then STOPPED=true; break; fi
    sleep 2
  done
  if [[ "$STOPPED" != true ]]; then
    warn "The backend has not stored a stop after 60 seconds. The extension may still be sending."
    yesno "Keep waiting?"
    [[ "$YN" == true ]] || { warn "Stopping without a stored stop. The export may be incomplete."; break; }
  fi
done
[[ "$STOPPED" == true ]] && say "The backend stored the stop."
sleep 3
stop_backend
say "Backend stopped."

# ── Stage 8 ───────────────────────────────────────────────────────────────
stage "Export and spot checks"
rm -rf "$EXPORT_DIR"
bun run scripts/probe-export.ts --data "$PROBE_DIR" --out "$EXPORT_DIR"
CAPTION_JSON=""
FRAME_JSON=""
AD_JSON=""

printf '\n'
say "Caption checks: for each sample the video opens at that time. Compare the text to what is spoken or shown, within 2 seconds."
say "Each opens a tab; close them as you go."
while IFS=$'\t' read -r -u 3 idx vid t text; do
  printf '\n'
  say "Caption sample $idx at ${t}s:"
  printf '    %s%s%s\n' "$BOLD" "$text" "$RESET"
  if [[ "$vid" != "-" ]]; then open_url "https://www.youtube.com/watch?v=$vid&t=${t}s"; else warn "No video id for this sample; find ${t}s in the lecture yourself."; fi
  yesno "Does the text match what is on screen or spoken within 2 seconds?"
  CAPTION_JSON+="${CAPTION_JSON:+,}{\"index\":$idx,\"match\":$YN}"
done 3< <(samples_tsv captions)

printf '\n'
say "Frame checks: each frame opens as an image."
while IFS=$'\t' read -r -u 3 idx vid t _; do
  printf '\n'
  say "Frame sample $idx (video time ${t}s):"
  open_file "$EXPORT_DIR/frames/$idx.jpg"
  yesno "Can you read the board text?"
  FRAME_JSON+="${FRAME_JSON:+,}{\"index\":$idx,\"readable\":$YN}"
done 3< <(samples_tsv frames)

AD_COUNT="$(( $(samples_tsv ad-frames | wc -l) + $(samples_tsv ad-passages | wc -l) + $(samples_tsv ad-spans | wc -l) ))"
if (( AD_COUNT > 0 )); then
  printf '\n'
  say "The capture recorded an ad. $AD_COUNT item(s) lie where ad evidence would land (the ad's own clock plus 5 s of slack), so check that none is an ad."
  while IFS=$'\t' read -r -u 3 idx vid t _; do
    printf '\n'
    say "Possible ad frame $idx (stamped ${t}s):"
    open_file "$EXPORT_DIR/frames/ad-$idx.jpg"
    yesno "Does this frame show an ad (not the lecture)?"
    AD_JSON+="${AD_JSON:+,}{\"kind\":\"frame\",\"index\":$idx,\"isAd\":$YN}"
  done 3< <(samples_tsv ad-frames)
  for kind in passage span; do
    while IFS=$'\t' read -r -u 3 idx vid t text; do
      printf '\n'
      say "Watched $kind $idx, starting at ${t}s:"
      printf '    %s%s%s\n' "$BOLD" "$text" "$RESET"
      if [[ "$vid" != "-" ]]; then open_url "https://www.youtube.com/watch?v=$vid&t=${t}s"; else warn "No video id for this item; find ${t}s in the lecture yourself."; fi
      yesno "Is this the lecture, not an ad?"
      if [[ "$YN" == true ]]; then IS_AD=false; else IS_AD=true; fi
      AD_JSON+="${AD_JSON:+,}{\"kind\":\"$kind\",\"index\":$idx,\"isAd\":$IS_AD}"
    done 3< <(samples_tsv "ad-${kind}s")
  done
fi

printf '{"captionChecks":[%s],"frameChecks":[%s],"adChecks":[%s],"observations":[%s]}\n' "$CAPTION_JSON" "$FRAME_JSON" "$AD_JSON" "$OBS_JSON" > "$PROBE_DIR/spot-results.json"
printf '{"off":{"dropped":%s,"total":%s},"on":{"dropped":%s,"total":%s}}\n' "$OFF_DROPPED" "$OFF_TOTAL" "$ON_DROPPED" "$ON_TOTAL" > "$PROBE_DIR/perf.json"
say "Saved $PROBE_DIR/spot-results.json and $PROBE_DIR/perf.json (gitignored)."

# ── Stage 9 ───────────────────────────────────────────────────────────────
stage "Report"
if bun run scripts/probe-report.ts --bundle "$EXPORT_DIR/bundle.json" --spot "$PROBE_DIR/spot-results.json" --perf "$PROBE_DIR/perf.json" --origin live --machine "$MACHINE_LABEL" --out "$PROBE_DIR/probe-report.md"; then
  say "The probe passed."
else
  say "The probe did not pass. That is a result, not an error."
fi
printf '\n'
say "Saved: $PROBE_DIR/probe-report.md"
say "Paste this report back in chat. Do not edit results."

finish
}

run_wizard "$@"; exit
